// 📁 src/pages/admin/DashboardHome.jsx
import { useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import StatResumePage from "./StatResumePage";
import StatCard from "@/components/admin/StatCard";
import { Loader2, Briefcase, FileText, UserPlus } from "lucide-react";
import api from "@/utils/api";
import toast from "react-hot-toast";

export default function DashboardHome() {
  const navigate = useNavigate();

  const [year, setYear] = useState(new Date().getFullYear());
  const [month, setMonth] = useState(""); // "01".."12" ou ""
  const [resume, setResume] = useState(null);
  const [loading, setLoading] = useState(true);

  // debounce simple (300ms) pour les filtres
  const debounceTimer = useRef(null);
  const paramsMemo = useMemo(() => ({ year, month }), [year, month]);

  useEffect(() => {
    const token = localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
    if (!token) {
      setLoading(false);
      return;
    }

    const ac = new AbortController();

    const fetchResume = () => {
      setLoading(true);
      api
        .get("/admin/stats/resume", {
          params: { year, month: month || undefined },
          signal: ac.signal,
        })
        .then(({ data }) => setResume(data))
        .catch((e) => {
          if (ac.signal.aborted) return;
          const status = e?.response?.status;
          const msg = e?.response?.data?.message || e?.message || "Erreur";
          // 429 = rate-limit : on affiche un message plus doux
          if (status === 429) {
            toast.error("Trop de requêtes. Réessaie dans un instant.");
          } else {
            toast.error(`Stats: ${status ?? ""} ${msg}`);
          }
          if (status === 401 || status === 403) {
            localStorage.removeItem("adminToken");
            sessionStorage.removeItem("adminToken");
            navigate("/admin/login", { replace: true });
          }
          setResume(null);
        })
        .finally(() => !ac.signal.aborted && setLoading(false));
    };

    // anti-bombardement : on attend 300ms après le dernier changement
    clearTimeout(debounceTimer.current);
    debounceTimer.current = setTimeout(fetchResume, 300);

    return () => {
      clearTimeout(debounceTimer.current);
      ac.abort();
    };
  }, [paramsMemo, navigate]);

  return (
    <div className="p-4 space-y-6">
      <h1 className="text-2xl font-bold text-gray-800">Tableau de bord</h1>

      {/* Filtres haut */}
      <div className="flex flex-wrap gap-2 items-center">
        <label className="text-sm text-muted-foreground">Filtrer par mois :</label>
        <select
          value={month}
          onChange={(e) => setMonth(e.target.value)}
          className="border rounded px-2 py-1 text-sm"
        >
          <option value="">Tous les mois</option>
          {["01","02","03","04","05","06","07","08","09","10","11","12"].map((m) => (
            <option key={m} value={m}>{m}</option>
          ))}
        </select>
      </div>

      {/* Tuiles résumé (issues de /admin/stats/resume) */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4" id="dashboard">
        {loading ? (
          <div className="col-span-4 flex justify-center items-center py-10">
            <Loader2 className="animate-spin h-6 w-6 text-gray-500" />
            <span className="ml-2">Chargement des statistiques...</span>
          </div>
        ) : (
          <>
            <StatCard title="Offres"       icon={<Briefcase className="text-blue-500" />}  value={resume?.total_offres ?? 0} />
            <StatCard title="Candidatures" icon={<FileText  className="text-green-500" />} value={resume?.total_candidatures ?? 0} />
            <StatCard title="Utilisateurs" icon={<UserPlus  className="text-yellow-500" />} value={resume?.total_utilisateurs ?? 0} />
            <StatCard title="Actualités"   icon={<FileText  className="text-red-500" />}   value={resume?.total_actualites ?? 0} />
          </>
        )}
      </div>

      {/* Bloc détaillé : on passe **la même réponse** */}
      <StatResumePage
        embedMode
        yearDefault={year}
        onYearChange={setYear}
        month={month}
        data={resume}  // 👈 plus d'appel interne
      />
    </div>
  );
}
